INSERT INTO `mc_orders` (`id`, `customer_id`, `customer_name`, `customer_email`, `customer_phone`, `customer_address`, `customer_city`, `customer_state`, `customer_pincode`, `items`, `subtotal`, `coupon_code`, `discount_amount`, `shipping_fee`, `total_amount`, `token_paid`, `balance_on_delivery`, `payment_method`, `payment_status`, `order_status`, `tracking_carrier`, `tracking_number`, `tracking_url`, `estimated_delivery`, `notes`, `created_at`, `updated_at`) VALUES ('MURLI-457702-467', NULL, 'Radhika Sharma', 'radhika@example.com', '9876543210', 'Flat 402, Lotus Towers', 'Rohtak', 'Haryana', '124001', '[{\"productId\":\"prod-1\",\"productCode\":\"MC\\/L-001\",\"productName\":\"Peacock Jharokha Wall Art (12x18\\u201d)\",\"price\":4100,\"quantity\":1,\"image\":\"\\/img-prodcut\\/IMG_4041.png\"}]', '4100.00', 'MURLI10', '410.00', '0.00', '3690.00', '3690.00', '0.00', 'UPI / QR', 'Failed', 'Shipped', 'Delhivery', 'DEL123456789', 'https://delhivery.com/track/DEL123456789', '2026-11-29', 'Customer requested bubble-wrapped premium wooden crate packaging.', '2026-08-24 11:30:00', '2026-11-26 11:51:32');
INSERT INTO `mc_products` (`id`, `code`, `slug`, `name`, `category`, `subcategory`, `price`, `mrp`, `stock`, `size`, `material`, `origin`, `artist`, `rating`, `reviews_count`, `images`, `video`, `folklore`, `description`, `featured`, `bestseller`, `tags`, `created_at`, `updated_at`) VALUES ('prod-1', 'MC/L-001', 'peacock-jharokha-wall-art', 'Peacock Jharokha Wall Art (12x18”)', 'Jharokhas & Frames', 'Carved Wooden Jharokha', '5200.00', '6500.00', '1', '12 x 18 inches', 'Solid Wood Arch, Clay Relief Paste, Mirror Glass Inlays, Antique Gold Finish', 'Delhi, India', 'Master Craftsman Murli Prasad', '5.00', '28', '[\"\\/img-prodcut\\/IMG_4041.png\",\"\\/img-prodcut\\/IMG_4041 2.png\"]', '', 'Jharokha window arches are royal architectural emblems inspired by Rajasthani and Haryanvi palace balconies. Adorned with the majestic Peacock (Mayur) — the sacred mount of Lord Murugan and Lord Krishna\'s beloved feather — this artwork invites royalty, grace, and positive spiritual vibrations into your entryway and living space.', 'Bring royal Indian heritage to your walls with this grand handcrafted Peacock Jharokha Wall Art. Features a hand-carved arch silhouette embellished with traditional Kutchi Lippan clay relief work and sparkling inlay mirrors. Finished in a regal antique patina and sealed with moisture-resistant protective lacquer.', '1', '1', '[\"bestseller\",\"featured\",\"jharokha\",\"peacock\"]', '2026-11-19 00:16:04', '2026-11-26 10:48:29');
INSERT INTO `mc_products` (`id`, `code`, `slug`, `name`, `category`, `subcategory`, `price`, `mrp`, `stock`, `size`, `material`, `origin`, `artist`, `rating`, `reviews_count`, `images`, `video`, `folklore`, `description`, `featured`, `bestseller`, `tags`, `created_at`, `updated_at`) VALUES ('prod-10', 'MC/L-010', 'ganesha-mini-art', 'Ganesha Mini Art (3”)', 'Diwali & Festive Decor', 'Lippan Spiritual Art', '199.00', '399.00', '25', '3 x 3 inches', 'Compact Wood Base, Clay Relief Paste, Mirror Glass Inlays, Golden Ochre Finish', 'Delhi, India', 'Master Craftsman Murli Prasad', '5.00', '44', '[\"\\/img-prodcut\\/IMG_3520.png\"]', '', 'Lord Ganesha (Vighnaharta) is the remover of obstacles and patron of beginnings, intellect, and good fortune. Having Lord Ganesha\'s handmade form blesses every endeavor.', 'Handmade 3-inch Lord Ganesha mini Lippan art frame crafted with sacred clay relief curves and sparkling mirrors. Ideal for home temples, office desks, car dashboards, and festive favors.', '1', '1', '[\"bestseller\",\"mini-art\",\"ganesha\",\"spiritual\"]', '2026-11-19 00:16:04', '2026-11-26 10:48:29');
INSERT INTO `mc_products` (`id`, `code`, `slug`, `name`, `category`, `subcategory`, `price`, `mrp`, `stock`, `size`, `material`, `origin`, `artist`, `rating`, `reviews_count`, `images`, `video`, `folklore`, `description`, `featured`, `bestseller`, `tags`, `created_at`, `updated_at`) VALUES ('prod-11', 'MC/L-011', 'lord-jagannath-mini-art', 'Lord Jagannath Mini Art (3”)', 'Lippan Art', 'Lippan Spiritual Art', '149.00', '299.00', '20', '3 x 3 inches', 'Compact Wood Base, Clay Relief, Mirrors, Sacred Acrylics', 'Delhi, India', 'Master Craftsman Murli Prasad', '4.80', '21', '[\"\\/img-prodcut\\/IMG_3507.png\"]', '', 'Lord Jagannath (Lord of the Universe) with his boundless large round eyes represents all-seeing divine compassion, universal love, and spiritual protection for all souls.', 'Devotional Lord Jagannath mini Lippan art frame depicting the sacred round eyes and divine countenance with handcrafted clay relief work, vivid traditional colors, and mirror accents.', '0', '0', '[\"mini-art\",\"jagannath\",\"spiritual\",\"puri\"]', '2026-11-19 00:16:04', '2026-11-26 10:48:29');
INSERT INTO `mc_products` (`id`, `code`, `slug`, `name`, `category`, `subcategory`, `price`, `mrp`, `stock`, `size`, `material`, `origin`, `artist`, `rating`, `reviews_count`, `images`, `video`, `folklore`, `description`, `featured`, `bestseller`, `tags`, `created_at`, `updated_at`) VALUES ('prod-12', 'MC/L-012', 'varli-mini-art', 'Varli Mini Art (3”)', 'Lippan Art', 'Lippan Wall Art', '149.00', '249.00', '18', '3 x 3 inches', 'Compact Wood Base, Clay Relief Paste, Mirror Accents, Terracotta Wash', 'Delhi, India', 'Master Craftsman Murli Prasad', '4.70', '18', '[\"\\/img-prodcut\\/IMG_3439.png\"]', '', 'Warli tribal art is a celebration of community dancing (Tarpa dance), mother nature, and universal harmony. Fused with Kutchi clay relief and mirrors, it honors timeless rural Indian roots.', 'Authentic Warli folk figures sculpted in miniature clay relief with mirror accents on a terracotta and earthy base. A lovely handcrafted accent for folk art enthusiasts.', '0', '0', '[\"mini-art\",\"warli\",\"folk\",\"tribal\"]', '2026-11-19 00:16:04', '2026-11-26 10:48:29');
INSERT INTO `mc_products` (`id`, `code`, `slug`, `name`, `category`, `subcategory`, `price`, `mrp`, `stock`, `size`, `material`, `origin`, `artist`, `rating`, `reviews_count`, `images`, `video`, `folklore`, `description`, `featured`, `bestseller`, `tags`, `created_at`, `updated_at`) VALUES ('prod-13', 'MC/L-013', 'matasya-rang-mini-art', 'Matasya Rang Mini Art (3”)', 'Lippan Art', 'Lippan Wall Art', '149.00', '299.00', '16', '3 x 3 inches', 'Compact Wood Base, Clay Relief, Mirrors, Teal & Coral Lacquer', 'Delhi, India', 'Master Craftsman Murli Prasad', '4.80', '15', '[\"\\/img-prodcut\\/IMG_3528.png\"]', '', 'The Matsya (Fish) motif is an auspicious emblem of life flow, fertility, adaptability, and salvation in Indian mythology, symbolising smooth sailing through all life journeys.', 'Handcrafted Matsya (Fish) motif mini Lippan artwork with sculpted flowing scales, radiant colors, and delicate mirror reflections on a compact wooden base.', '0', '0', '[\"mini-art\",\"matsya\",\"fish\",\"folk\"]', '2026-11-19 00:16:04', '2026-11-26 10:48:29');
INSERT INTO `mc_products` (`id`, `code`, `slug`, `name`, `category`, `subcategory`, `price`, `mrp`, `stock`, `size`, `material`, `origin`, `artist`, `rating`, `reviews_count`, `images`, `video`, `folklore`, `description`, `featured`, `bestseller`, `tags`, `created_at`, `updated_at`) VALUES ('prod-14', 'MC/L-014', 'shubh-labh-lippan-art-3-inch-pair', 'Shubh-Labh lippan art 3”', 'Diwali & Festive Decor', 'Customised Shubh-Labh', '249.00', '499.00', '25', '3 x 3 inches (Pair of 2)', 'Solid Round Wood Base Pair, Clay Relief Craft, Sparkle Mirrors, Hanging Pearl Tassels, Red & Gold Lacquer', 'Delhi, India', 'Master Craftsman Murli Prasad', '5.00', '59', '[\"\\/img-prodcut\\/shubh_3inch.jpg\",\"\\/img-prodcut\\/labh_3inch.jpg\"]', '', 'Shubh (Auspiciousness) and Labh (Prosperity/Profit) are the divine sons of Lord Ganesha and Goddesses Riddhi-Siddhi. Hanging a Shubh-Labh pair on the main door entrance invites continuous prosperity, divine protection, and joy.', 'Handcrafted pair of 3-inch Shubh-Labh Lippan art plaques with sculpted clay relief lettering, sparkling faceted mirror inlays, rich festive red and gold lacquer, and hanging pearl bead tassels.', '1', '1', '[\"bestseller\",\"featured\",\"shubh-labh\",\"door-decor\",\"diwali\",\"pair\"]', '2026-11-19 00:16:04', '2026-11-26 10:48:29');
INSERT INTO `mc_products` (`id`, `code`, `slug`, `name`, `category`, `subcategory`, `price`, `mrp`, `stock`, `size`, `material`, `origin`, `artist`, `rating`, `reviews_count`, `images`, `video`, `folklore`, `description`, `featured`, `bestseller`, `tags`, `created_at`, `updated_at`) VALUES ('prod-15', 'MC/L-015', 'khatushyam-ji-temple-decor-mini-art', 'Khatushyam Ji Temple Decor Mini Art (3”)', 'Shyam Ji Decor', 'Shyam Baba Shringar & Flowers', '249.00', '499.00', '35', '3 x 3 inches', 'Compact Wood Base, Clay Relief, Morpankh motifs, Mirror Glass Inlays', 'Delhi, India', 'Master Craftsman Murli Prasad', '5.00', '65', '[\"\\/img-prodcut\\/IMG_4158.png\"]', '', 'Khatu Shyam Baba (Haare Ka Sahara, Baba Shyam Hamara) is the beloved lord of Kaliyuga. Devotees keep his sacred form in their mandir and workspace as a constant source of divine grace, courage, and unconditional faith (Bhav).', 'Sacred Khatu Shyam Baba temple decor mini art frame. Handcrafted with devotional clay relief, peacock feather motifs (Mor Pankh), and reflective mirror accents. A holy adornment for home temples and sacred gifts.', '1', '1', '[\"bestseller\",\"featured\",\"shyam-ji\",\"khatu-baba\",\"temple-decor\"]', '2026-11-19 00:16:04', '2026-11-26 10:48:29');
INSERT INTO `mc_products` (`id`, `code`, `slug`, `name`, `category`, `subcategory`, `price`, `mrp`, `stock`, `size`, `material`, `origin`, `artist`, `rating`, `reviews_count`, `images`, `video`, `folklore`, `description`, `featured`, `bestseller`, `tags`, `created_at`, `updated_at`) VALUES ('prod-16', 'MC/L-016', 'lord-ganesha-temple-decor-mini-art-3-inch', 'Lord Ganesha temple decor mini art 3”', 'Lippan Art', 'Lippan Spiritual Art', '249.00', '499.00', '30', '3 x 3 inches', 'Handcrafted Wooden Disc, Faceted Gemstones, Sacred Ganesha Art, Pearl Beaded Tassel, Velvet Finish', 'Delhi, India', 'Master Craftsman Murli Prasad', '5.00', '42', '[\"\\/img-prodcut\\/IMG_3371.png\"]', '', 'Lord Ganesha (Vighnaharta) is the sacred harbinger of auspiciousness, prosperity (Riddhi-Siddhi), and wisdom. Having this handcrafted Ganesha mini art in your mandir, entrance, or dashboard brings continuous divine protection and joy.', 'Handcrafted 3-inch Lord Ganesha temple decor mini art with radiant yellow background, sparkling crystal gemstone border, sacred Ganesha icon at the center, and auspicious hanging pearl tassel. Perfect for mandir, car dashboard, entrance doors, and festive gifting.', '1', '1', '[\"bestseller\",\"featured\",\"ganesha\",\"mini-art\",\"temple-decor\",\"spiritual\"]', '2026-11-19 00:16:04', '2026-11-26 10:48:29');
INSERT INTO `mc_products` (`id`, `code`, `slug`, `name`, `category`, `subcategory`, `price`, `mrp`, `stock`, `size`, `material`, `origin`, `artist`, `rating`, `reviews_count`, `images`, `video`, `folklore`, `description`, `featured`, `bestseller`, `tags`, `created_at`, `updated_at`) VALUES ('prod-17', 'MC/L-017', 'mahadev-damru-wall-decor-8-inch', 'Mahadev Damru wall decor 8”', 'Lippan Art', 'Lippan Spiritual Art', '1999.00', '2499.00', '0', '8 x 8 inches', 'Moisture-resistant Engineered Board, Clay Relief Paste, Mirror Glass Pieces, Protective Lacquer', 'Delhi, India', 'Master Craftsman Murli Prasad', '4.90', '29', '[\"\\/img-prodcut\\/IMG_2849.png\"]', '', 'Lord Shiva\'s Damru represents the cosmic sound of creation (Nada Brahma), while the Trishul signifies cosmic balance and spiritual strength. This sacred Lippan artwork brings meditative tranquility, peace, and divine energy into your home.', 'Handcrafted 8-inch Mahadev Damru & Trishul spiritual wall decor piece featuring authentic Kutchi mud clay relief, shimmering mirrors, and sacred Shaivite symbols. Created with devotion to bring peace, strength, and auspicious cosmic vibrations to your home mandir or living room.', '1', '1', '[\"bestseller\",\"featured\",\"mahadev\",\"damru\",\"shiva\",\"spiritual\",\"wall-decor\"]', '2026-11-19 00:16:04', '2026-11-26 10:48:29');
INSERT INTO `mc_products` (`id`, `code`, `slug`, `name`, `category`, `subcategory`, `price`, `mrp`, `stock`, `size`, `material`, `origin`, `artist`, `rating`, `reviews_count`, `images`, `video`, `folklore`, `description`, `featured`, `bestseller`, `tags`, `created_at`, `updated_at`) VALUES ('prod-18', 'MC/S-001', 'basanti-pushp-poshaak-4-feet', 'Basanti Pushp Poshaak', 'Shyam Ji Decor', 'Shyam Baba Dresses & Poshak', '5999.00', '7499.00', '8', '4 feet (customise)', 'Heavy Silk Fabric, Intricate Zari Embroidery, Golden Lace, Stone & Moti Work', 'Delhi, India', 'Master Craftsman Murli Prasad', '5.00', '38', '[\"\\/img-prodcut\\/IMG_4212.png\"]', '', 'Adorning Khatu Shyam Baba with vibrant Basanti (yellow) floral poshaak is an offering of pure love and devotional joy. The golden yellow hues symbolize spring blessings, warmth, and auspicious celebration.', 'Exquisite Basanti Pushp Poshaak for Khatu Shyam Baba. Handcrafted with rich floral zari embroidery, intricate moti, sequins, and royal golden borders. Made with love and devotion for grand temple shringar and festive darshan. Available in standard 4 feet size with custom size tailoring on request.', '1', '1', '[\"bestseller\",\"featured\",\"shyam-baba\",\"poshak\",\"basanti\",\"dress\",\"khatu-shyam\"]', '2026-11-19 00:16:04', '2026-11-26 10:48:29');
INSERT INTO `mc_products` (`id`, `code`, `slug`, `name`, `category`, `subcategory`, `price`, `mrp`, `stock`, `size`, `material`, `origin`, `artist`, `rating`, `reviews_count`, `images`, `video`, `folklore`, `description`, `featured`, `bestseller`, `tags`, `created_at`, `updated_at`) VALUES ('prod-19', 'MC/S-002', 'pachrangi-hariyali-poshak-4-feet', 'Pachrangi Hariyali Poshak', 'Shyam Ji Decor', 'Shyam Baba Dresses & Poshak', '5999.00', '7499.00', '7', '4 feet (customise)', 'Premium Embroidered Silk/Brocade, Multi-color Threadwork, Zari Borders, Sequins', 'Delhi, India', 'Master Craftsman Murli Prasad', '5.00', '31', '[\"\\/img-prodcut\\/IMG_4213.png\"]', '', 'The Panchrangi (five sacred colours) combined with fresh green signifies nature\'s abundance, harmony, and heartfelt devotion offered at the lotus feet of Shyam Baba.', 'Vibrant Pachrangi Hariyali Poshak for Khatu Shyam Baba, featuring five sacred harmonious shades interwoven with lush green tones, delicate floral motifs, heavy border work, and embellished sequins. Perfect for Sawan, Ekadashi, and special deity shringar.', '1', '1', '[\"bestseller\",\"featured\",\"shyam-baba\",\"pachrangi\",\"hariyali\",\"poshak\",\"khatu-shyam\"]', '2026-11-19 00:16:04', '2026-11-26 10:48:29');
INSERT INTO `mc_products` (`id`, `code`, `slug`, `name`, `category`, `subcategory`, `price`, `mrp`, `stock`, `size`, `material`, `origin`, `artist`, `rating`, `reviews_count`, `images`, `video`, `folklore`, `description`, `featured`, `bestseller`, `tags`, `created_at`, `updated_at`) VALUES ('prod-2', 'MC/L-002', 'lotus-mandala-wall-art', 'Lotus Mandala Wall Art (12x12”)', 'Lippan Art', 'Lippan Mandala Art', '3199.00', '3999.00', '10', '12 x 12 inches', 'Clay Relief Paste, Mirror Glass pieces, Premium Engineered MDF Board', 'Delhi, India', 'Master Craftsman Murli Prasad', '4.90', '34', '[\"\\/img-prodcut\\/IMG_3495.png\"]', '', 'The Lotus (Kamal) is the timeless Indian symbol of purity, beauty, and spiritual blossoming above worldly waters. In combination with sacred circular mandala geometry, it brings centered calmness, tranquility, and harmony to meditation rooms and living sanctuaries.', 'An exquisite handcrafted 12x12 inch Lippan Art panel featuring concentric mandala coils, blooming lotus petal relief work, and dozens of precision-cut sparkling mirrors. Crafted with organic clay relief paste over a moisture-sealed MDF base.', '1', '1', '[\"bestseller\",\"featured\",\"mandala\",\"lotus\"]', '2026-11-19 00:16:04', '2026-11-26 10:48:29');
