INSERT INTO `mc_products` (`id`, `code`, `slug`, `name`, `category`, `subcategory`, `price`, `mrp`, `stock`, `size`, `material`, `origin`, `artist`, `rating`, `reviews_count`, `images`, `video`, `folklore`, `description`, `featured`, `bestseller`, `tags`, `created_at`, `updated_at`) VALUES ('prod-24', 'MC/S-007', 'kamal-kalangi', 'Kamal Kalangi', 'Shyam Ji Decor', 'Shyam Baba Kalangi', '1599.00', '1999.00', '15', 'Customise', 'Handpicked Peacock Feathers, Lotus Motif Base, Kundan Stone Embellishments, Velvet & Golden Zari Ribbons', 'Delhi, India', 'Master Craftsman Murli Prasad', '5.00', '24', '[\"\\/img-prodcut\\/IMG_4448.png\"]', '', 'The sacred lotus (Kamal) combined with Kalangi symbolizes divine grace, purity, and royal adornment offered for the holy mukut of Khatu Shyam Baba.', 'Exquisite handcrafted Kamal Kalangi for Khatu Shyam Baba mukut and sacred deity worship. Artfully designed with a central blossoming lotus motif, natural peacock plumes, sparkling kundan embellishments, and golden threadwork with a comfortable stand/wrapped base.', '1', '1', '[\"bestseller\",\"featured\",\"shyam-ji\",\"kalangi\",\"kamal-kalangi\",\"shringar\",\"khatu-shyam\"]', '2026-11-19 00:16:04', '2026-11-26 10:48:29');
INSERT INTO `mc_products` (`id`, `code`, `slug`, `name`, `category`, `subcategory`, `price`, `mrp`, `stock`, `size`, `material`, `origin`, `artist`, `rating`, `reviews_count`, `images`, `video`, `folklore`, `description`, `featured`, `bestseller`, `tags`, `created_at`, `updated_at`) VALUES ('prod-25', 'MC/L-018', 'diwali-special-om-swastik-laxmi-charan-temple-decor-12x18', 'Diwali special OM, Swastik, Laxmi charan Temple decor (12X18)', 'Diwali & Festive Decor', 'Lippan Spiritual Art', '5200.00', '6500.00', '1', '12 x 18 inches', 'High Density MDF Board, Clay Relief Paste, Mirror Glass Inlays, Auspicious Festive Pigments, Protective Varnish', 'Delhi, India', 'Master Craftsman Murli Prasad', '5.00', '38', '[\"\\/img-prodcut\\/IMG_4454.png\"]', '', 'Uniting the primordial sound OM, the cosmic balance of the Swastik, and the holy charans of Goddess Mahalakshmi, this sacred temple decor brings auspiciousness, prosperity, and divine protection to your home.', 'Magnificent handcrafted 12x18 inch Diwali special temple decor panel featuring sacred OM, Swastik, and Maa Laxmi Charan. Sculpted with authentic Kutchi Lippan clay relief craft, glistening mirror inlays, and vibrant auspicious festive pigments.', '1', '1', '[\"bestseller\",\"featured\",\"diwali\",\"om\",\"swastik\",\"laxmi-charan\",\"temple-decor\",\"lippan-art\"]', '2026-11-19 00:16:04', '2026-11-26 10:48:29');
