INSERT INTO `mc_products` (`id`, `code`, `slug`, `name`, `category`, `subcategory`, `price`, `mrp`, `stock`, `size`, `material`, `origin`, `artist`, `rating`, `reviews_count`, `images`, `video`, `folklore`, `description`, `featured`, `bestseller`, `tags`, `created_at`, `updated_at`) VALUES ('prod-28', 'MC/S-010', 'kanhaiya-kundan-kalangi', 'Kanhaiya kundan Kalangi', 'Shyam Ji Decor', 'Shyam Baba Kalangi', '1499.00', '1999.00', '14', 'Customise', 'Pristine Peacock Feathers, Royal Blue Velvet Crest, Premium Kundan Stones, Red Floral Accents, Cascading Pearl Drops, Hand-carved Wooden Stand', 'Delhi, India', 'Master Craftsman Murli Prasad', '5.00', '22', '[\"\\/img-prodcut\\/IMG_4603.png\"]', '', 'Dedicated to Kanhaiya, this opulent Kundan Kalangi reflects the eternal luster and royal magnificence of Shyam Baba\'s sacred darbar.', 'Opulent Kanhaiya Kundan Kalangi featuring a handcrafted royal blue velvet crest studded with premium sparkling kundan stones, vibrant red floral rose accents, pristine peacock plumes, and delicate cascading pearl drops. Displayed gracefully on an artisanal hand-carved wooden stand for mandir shringar and sacred decor.', '1', '1', '[\"bestseller\",\"featured\",\"shyam-ji\",\"kalangi\",\"kanhaiya-kundan\",\"shringar\",\"mukut\"]', '2026-11-19 00:16:04', '2026-11-26 10:48:29');
INSERT INTO `mc_products` (`id`, `code`, `slug`, `name`, `category`, `subcategory`, `price`, `mrp`, `stock`, `size`, `material`, `origin`, `artist`, `rating`, `reviews_count`, `images`, `video`, `folklore`, `description`, `featured`, `bestseller`, `tags`, `created_at`, `updated_at`) VALUES ('prod-29', 'MC/S-013', 'shyam-darbar-mala', 'Shyam Darbar Mala', 'Shyam Ji Decor', 'Shyam Baba Haar', '5599.00', '6999.00', '8', 'Customise', 'Plush Royal Blue Velvet, Handcrafted \'Jai Shree Shyam\' Centerpiece, Morpankh Medallions, Ruby & Emerald Gemstone Work, Scalloped Gold Gotta Lace, Hanging Hooks', 'Delhi, India', 'Master Craftsman Murli Prasad', '5.00', '29', '[\"\\/img-prodcut\\/IMG_4606.png\"]', '', 'The Shyam Darbar Mala is crafted for royal raj shringar, bearing the sacred inscription \'जय श्री श्याम\' and holy Morpankh motifs to offer sovereignty, eternal devotion, and divine surrender to Baba Shyam.', 'Grand artisanal Shyam Darbar Mala handcrafted for Khatu Shyam Baba raj shringar. Features rich royal blue velvet embellished with an ornate central medallion inscribed with \'जय श्री श्याम\', surrounded by radiant lotus petal stone settings, auspicious Morpankh medallions, ruby and emerald gemstone accents, and delicate scalloped golden gotta borders.', '1', '1', '[\"bestseller\",\"featured\",\"shyam-ji\",\"darbar-mala\",\"jai-shree-shyam\",\"haar\",\"shringar\",\"khatu-baba\"]', '2026-11-19 00:16:04', '2026-11-26 10:48:29');
INSERT INTO `mc_products` (`id`, `code`, `slug`, `name`, `category`, `subcategory`, `price`, `mrp`, `stock`, `size`, `material`, `origin`, `artist`, `rating`, `reviews_count`, `images`, `video`, `folklore`, `description`, `featured`, `bestseller`, `tags`, `created_at`, `updated_at`) VALUES ('prod-3', 'MC/L-003', 'teal-gold-mandala-art', 'Teal & Gold Mandala Art (12x12”)', 'Lippan Art', 'Lippan Mandala Art', '3199.00', '3999.00', '9', '12 x 12 inches', 'Refined Clay Paste, Inlay Mirror Glass, Metallic Gold Pigments, MDF Base', 'Delhi, India', 'Master Craftsman Murli Prasad', '4.90', '41', '[\"\\/img-prodcut\\/IMG_3519.png\"]', '', 'Teal represents renewal, open communication, and clarity, while royal gold leaf tones symbolize abundance and solar vitality. The radiating mandala patterns create a focal point of positive energy that lifts the mood of any room.', 'Stunning contrast of deep royal teal and luminous gold accents handcrafted with traditional Lippan mud-mirror relief art. The intricate radial clay coil work and shimmering glass mirrors reflect ambient lighting beautifully day and night.', '1', '1', '[\"bestseller\",\"featured\",\"mandala\",\"teal-gold\"]', '2026-11-19 00:16:04', '2026-11-26 10:48:29');
INSERT INTO `mc_products` (`id`, `code`, `slug`, `name`, `category`, `subcategory`, `price`, `mrp`, `stock`, `size`, `material`, `origin`, `artist`, `rating`, `reviews_count`, `images`, `video`, `folklore`, `description`, `featured`, `bestseller`, `tags`, `created_at`, `updated_at`) VALUES ('prod-30', 'MC/S-011', 'morpankh-velvet-haar', 'Morpankh velvet Haar', 'Shyam Ji Decor', 'Shyam Baba Haar', '5599.00', '6999.00', '8', 'Customise', 'Heavy Velvet Fabric, Morpankh Embroidery & Motifs, Stone & Pearl Embellishments, Golden Gotta Patti', 'Delhi, India', 'Master Craftsman Murli Prasad', '5.00', '33', '[\"\\/img-prodcut\\/IMG_4616.png\"]', '', 'The Morpankh (peacock feather) is the supreme ornament of Lord Krishna and Shyam Baba. Adorning the deity with this velvet haar brings peace, purity, and spiritual elevation.', 'Exquisite Morpankh Velvet Haar for Khatu Shyam Baba deity shringar. Crafted on rich dark velvet with intricate peacock feather motif embroidery, radiant stones, pearl fringe accents, and gold lace trims.', '1', '1', '[\"bestseller\",\"featured\",\"shyam-ji\",\"morpankh-haar\",\"velvet-haar\",\"shringar\"]', '2026-11-19 00:16:04', '2026-11-26 10:48:29');
INSERT INTO `mc_products` (`id`, `code`, `slug`, `name`, `category`, `subcategory`, `price`, `mrp`, `stock`, `size`, `material`, `origin`, `artist`, `rating`, `reviews_count`, `images`, `video`, `folklore`, `description`, `featured`, `bestseller`, `tags`, `created_at`, `updated_at`) VALUES ('prod-31', 'MC/S-012', 'swastik-velvet-choker-haar', 'Swastik velvet Choker Haar', 'Shyam Ji Decor', 'Shyam Baba Haar', '5599.00', '6999.00', '0', 'Customise', 'Royal Blue Velvet, Auspicious Swastik & \'श्याम\' Motifs, Crystal Gemstones, Triple Layer Beaded Strands, Gold Zari Lace', 'Delhi, India', 'Master Craftsman Murli Prasad', '5.00', '25', '[\"\\/img-prodcut\\/IMG_4618.png\"]', '', 'The holy Swastik represents universal auspiciousness, good fortune, and cosmic protection. Offering this sacred choker haar brings heavenly blessings into the devotee\'s life.', 'Regal Swastik Velvet Choker Haar handcrafted for Khatu Shyam Baba deity shringar. Features plush royal blue velvet embellished with an auspicious central \'श्याम\' medallion, dual Swastik emblems, intricate floral vine crystal embroidery, and triple cascading crystal bead drop strands.', '1', '1', '[\"bestseller\",\"featured\",\"shyam-ji\",\"swastik-haar\",\"velvet-choker\",\"shringar\"]', '2026-11-19 00:16:04', '2026-11-26 10:48:29');
INSERT INTO `mc_products` (`id`, `code`, `slug`, `name`, `category`, `subcategory`, `price`, `mrp`, `stock`, `size`, `material`, `origin`, `artist`, `rating`, `reviews_count`, `images`, `video`, `folklore`, `description`, `featured`, `bestseller`, `tags`, `created_at`, `updated_at`) VALUES ('prod-32', 'MC/L-019', 'lord-ganesha-temple-wall-decor', 'Lord Ganesha temple/wall decor', 'Lippan Art', 'Lippan Spiritual Art', '4100.00', '5500.00', '1', '14 x 14 inches (Round)', 'Traditional Clay Relief Paste, Inlay Mirror Glass (Abhala Work), Gemstone Crystal Accents, Premium MDF Base, Moisture-Resistant Protective Lacquer', 'Delhi, India', 'Master Craftsman Murli Prasad', '5.00', '26', '[\"\\/img-prodcut\\/lord_ganesha_temple_wall_decor.jpg\"]', '', 'Lord Ganesha (Vighnaharta) is revered as the remover of obstacles, the bestower of Riddhi-Siddhi (prosperity and wisdom), and the lord of auspicious beginnings. Placing this divine handcrafted Lippan wall decor in your temple or living sanctuary invites pure positive energy, harmony, and celestial blessings.', 'Magnificent handcrafted circular Lord Ganesha temple and wall decor artwork crafted with traditional Kutchi Lippan clay relief craft. Features a beautifully sculpted Lord Ganesha holding sacred modaks in divine blessing posture, embellished with sparkling crystal gemstone jewelry, sacred mukut crown, radiating lotus flower motifs, glistening teardrop mirror inlays (abhala craft), braided gold border, and dual-tone auspicious festive rims.', '1', '1', '[\"bestseller\",\"featured\",\"ganesha\",\"lord-ganesha\",\"temple-decor\",\"wall-decor\",\"lippan-art\",\"spiritual\"]', '2026-11-19 00:16:04', '2026-11-26 10:48:29');
INSERT INTO `mc_products` (`id`, `code`, `slug`, `name`, `category`, `subcategory`, `price`, `mrp`, `stock`, `size`, `material`, `origin`, `artist`, `rating`, `reviews_count`, `images`, `video`, `folklore`, `description`, `featured`, `bestseller`, `tags`, `created_at`, `updated_at`) VALUES ('prod-34', 'MC/S-014', 'neelmani-shingar-haar', 'Neelmani Shingar Haar', 'Shyam Ji Decor', 'Shyam Baba Haar', '6399.00', '7999.00', '8', 'Customise', 'Deep Sapphire Velvet, Neelam Gemstone Accents, Golden Zari Embroidery, Cascading Pearl Drops, Golden Lace Border', 'Delhi, India', 'Master Craftsman Murli Prasad', '5.00', '18', '[\"\\/img-prodcut\\/IMG_4748.png\"]', '', 'Neelam (Sapphire) is the divine gem associated with the deep cosmic blue of Shyam Baba. Adorning Baba with this resplendent Neelmani Haar is an offering of deep devotion, protection, and eternal grace.', 'Exquisite handcrafted Neelmani Shingar Haar for Khatu Shyam Baba deity shringar. Crafted with rich deep sapphire blue velvet, luminous neelam gemstone accents, intricate golden embroidery, and cascading pearl drop strands. A regal offering for grand temple shringar and special devotional occasions.', '1', '1', '[\"bestseller\",\"featured\",\"shyam-ji\",\"haar\",\"neelmani\",\"shringar\",\"khatu-shyam\"]', '2026-11-19 00:16:04', '2026-11-26 10:48:29');
INSERT INTO `mc_products` (`id`, `code`, `slug`, `name`, `category`, `subcategory`, `price`, `mrp`, `stock`, `size`, `material`, `origin`, `artist`, `rating`, `reviews_count`, `images`, `video`, `folklore`, `description`, `featured`, `bestseller`, `tags`, `created_at`, `updated_at`) VALUES ('prod-35', 'MC/S-015', 'kalyug-ke-avatar-haar', 'Kalyug ke Avatar Haar', 'Shyam Ji Decor', 'Shyam Baba Haar', '4799.00', '5999.00', '10', 'Customise', 'Rich Velvet, Golden Zari Threadwork, Gemstone Accents, Pearl Lace Border, Devotional Motifs', 'Delhi, India', 'Master Craftsman Murli Prasad', '5.00', '21', '[\"\\/img-prodcut\\/IMG_4749.png\"]', '', 'Khatu Shyam Baba is revered as the Avatar of Kaliyuga — the lord who accepts even the most humble devotee. This haar is crafted as a devotional tribute to Baba\'s infinite compassion and his divine promise to his bhakts in this age.', 'Sacred handcrafted Kalyug ke Avatar Haar for Khatu Shyam Baba. Features rich velvet base embellished with intricate golden threadwork, radiant gemstone accents, auspicious devotional motifs, and delicate pearl lace borders. A divine offering for daily shringar and special pooja occasions.', '1', '1', '[\"bestseller\",\"featured\",\"shyam-ji\",\"haar\",\"kalyug-avatar\",\"shringar\",\"khatu-shyam\"]', '2026-11-19 00:16:04', '2026-11-26 10:48:29');
INSERT INTO `mc_products` (`id`, `code`, `slug`, `name`, `category`, `subcategory`, `price`, `mrp`, `stock`, `size`, `material`, `origin`, `artist`, `rating`, `reviews_count`, `images`, `video`, `folklore`, `description`, `featured`, `bestseller`, `tags`, `created_at`, `updated_at`) VALUES ('prod-36', 'MC/S-016', 'mayur-kamal-avatar-haar', 'Mayur Kamal Avatar Haar', 'Shyam Ji Decor', 'Shyam Baba Haar', '6399.00', '7999.00', '7', 'Customise', 'Premium Velvet, Peacock Motif Embroidery, Lotus Centerpiece, Kundan Stones, Golden Gotta Patti, Pearl Drops', 'Delhi, India', 'Master Craftsman Murli Prasad', '5.00', '16', '[\"\\/img-prodcut\\/IMG_4750.png\"]', '', 'The sacred Mayur (Peacock) is Shyam Baba\'s beloved symbol of divine beauty, and the Kamal (Lotus) represents purity rising above worldly distractions. Together they form a deeply auspicious offering for the Lord\'s shringar.', 'Magnificent handcrafted Mayur Kamal Avatar Haar for Khatu Shyam Baba. Adorned with intricate peacock feather motifs, blooming lotus centerpiece, shimmering kundan stones, golden gotta patti borders, and lustrous pearl drop accents. Perfect for grand festival shringar and Ekadashi darshan.', '1', '1', '[\"bestseller\",\"featured\",\"shyam-ji\",\"haar\",\"mayur-kamal\",\"shringar\",\"khatu-shyam\"]', '2026-11-19 00:16:04', '2026-11-26 10:48:29');
INSERT INTO `mc_products` (`id`, `code`, `slug`, `name`, `category`, `subcategory`, `price`, `mrp`, `stock`, `size`, `material`, `origin`, `artist`, `rating`, `reviews_count`, `images`, `video`, `folklore`, `description`, `featured`, `bestseller`, `tags`, `created_at`, `updated_at`) VALUES ('prod-37', 'MC/S-017', 'royal-mayur-shyam-haar', 'Royal Mayur Shyam Haar', 'Shyam Ji Decor', 'Shyam Baba Haar', '4479.00', '5599.00', '9', 'Customise', 'Royal Velvet, Iridescent Peacock Motifs, Sparkling Stones, Golden Lace Trim, Pearl Bead Strands', 'Delhi, India', 'Master Craftsman Murli Prasad', '4.90', '19', '[\"\\/img-prodcut\\/IMG_4752.png\"]', '', 'The royal peacock is the most beloved adornment of Shyam Baba\'s divine form. Offering a Mayur-inspired haar at Baba\'s feet brings divine grace, peace, and blessings of abundance into the devotee\'s life.', 'Regal handcrafted Royal Mayur Shyam Haar for Khatu Shyam Baba shringar. Crafted with luxurious velvet featuring royal peacock motifs in vibrant iridescent tones, sparkling stone embellishments, golden lace trim, and flowing pearl bead strands.', '1', '1', '[\"bestseller\",\"featured\",\"shyam-ji\",\"haar\",\"royal-mayur\",\"shringar\",\"khatu-shyam\"]', '2026-11-19 00:16:04', '2026-11-26 10:48:29');
INSERT INTO `mc_products` (`id`, `code`, `slug`, `name`, `category`, `subcategory`, `price`, `mrp`, `stock`, `size`, `material`, `origin`, `artist`, `rating`, `reviews_count`, `images`, `video`, `folklore`, `description`, `featured`, `bestseller`, `tags`, `created_at`, `updated_at`) VALUES ('prod-38', 'MC/S-018', 'royal-peacock-kalangi', 'Royal Peacock Kalangi', 'Shyam Ji Decor', 'Shyam Baba Kalangi', '2399.00', '2999.00', '12', 'Customise', 'Premium Peacock Plumes, Kundan Stone Accents, Golden Gotta Patti, Cascading Pearl Tassels, Velvet Base', 'Delhi, India', 'Master Craftsman Murli Prasad', '4.90', '14', '[\"\\/img-prodcut\\/IMG_4753.png\"]', '', 'The royal peacock feather is the supreme adornment of Lord Krishna and Khatu Shyam Baba\'s sacred mukut. Offering a handcrafted Peacock Kalangi at Baba\'s crown brings divine joy, protection, and celestial blessings.', 'Exquisite handcrafted Royal Peacock Kalangi for Khatu Shyam Baba mukut adornment. Assembled with premium iridescent peacock plumes in a graceful royal spread, embellished with kundan stone accents, golden gotta patti borders, and delicate cascading pearl tassels.', '1', '0', '[\"featured\",\"shyam-ji\",\"kalangi\",\"royal-peacock\",\"shringar\",\"khatu-shyam\"]', '2026-11-19 00:16:04', '2026-11-26 10:48:29');
INSERT INTO `mc_products` (`id`, `code`, `slug`, `name`, `category`, `subcategory`, `price`, `mrp`, `stock`, `size`, `material`, `origin`, `artist`, `rating`, `reviews_count`, `images`, `video`, `folklore`, `description`, `featured`, `bestseller`, `tags`, `created_at`, `updated_at`) VALUES ('prod-39', 'MC/S-019', 'royal-pitambari-poshak-vasantpanchmi', 'Royal Pitambari Poshak (Vasantpanchmi Special)', 'Shyam Ji Decor', 'Shyam Baba Dresses & Poshak', '6399.00', '7999.00', '0', 'Customise', 'Rich Golden-Yellow Silk, Heavy Zari Embroidery, Floral Motifs, Golden Gotta Patti, Stone & Sequin Work', 'Delhi, India', 'Master Craftsman Murli Prasad', '5.00', '23', '[\"\\/img-prodcut\\/IMG_4755.png\"]', '', 'Pitambar (golden yellow) is the divine color of Vasant Panchami, symbolizing the arrival of spring, wisdom of Goddess Saraswati, and the radiant aura of Lord Vishnu. Adorning Shyam Baba in Pitambari poshak on this sacred day invites divine blessings, knowledge, and auspicious new beginnings.', 'Magnificent Royal Pitambari Poshak specially crafted for Vasant Panchami shringar of Khatu Shyam Baba. Made with rich golden-yellow silk fabric adorned with intricate zari embroidery, blooming floral motifs, heavy golden gotta patti borders, sparkling stone and sequin work.', '1', '1', '[\"bestseller\",\"featured\",\"shyam-ji\",\"poshak\",\"pitambari\",\"vasantpanchmi\",\"khatu-shyam\"]', '2026-11-19 00:16:04', '2026-11-26 10:48:29');
INSERT INTO `mc_products` (`id`, `code`, `slug`, `name`, `category`, `subcategory`, `price`, `mrp`, `stock`, `size`, `material`, `origin`, `artist`, `rating`, `reviews_count`, `images`, `video`, `folklore`, `description`, `featured`, `bestseller`, `tags`, `created_at`, `updated_at`) VALUES ('prod-4', 'MC/L-004', 'utsav-mandala-wall-art', 'Utsav Mandala Wall Art (8x8”)', 'Lippan Art', 'Lippan Mandala Art', '1599.00', '1999.00', '0', '8 x 8 inches', 'Clay Relief Paste, Mirror Glass, Vibrant Acrylics, MDF Board', 'Delhi, India', 'Master Craftsman Murli Prasad', '4.80', '19', '[\"\\/img-prodcut\\/IMG_3299.png\"]', '', 'Utsav (Festival) represents celebration, joy, and collective festivity. In Indian tradition, circular geometric wall decorations are hung during auspicious occasions to welcome deities and guests with cheerful blessings.', 'Hand-sculpted 8x8 inch Lippan mandala art panel bursting with festive colors, geometric mud-clay relief lines, and diamond mirrors. Ideal for gallery walls, entryway niches, or thoughtful festive gifts.', '1', '0', '[\"featured\",\"mandala\",\"festive\"]', '2026-11-19 00:16:04', '2026-11-26 10:48:29');
INSERT INTO `mc_products` (`id`, `code`, `slug`, `name`, `category`, `subcategory`, `price`, `mrp`, `stock`, `size`, `material`, `origin`, `artist`, `rating`, `reviews_count`, `images`, `video`, `folklore`, `description`, `featured`, `bestseller`, `tags`, `created_at`, `updated_at`) VALUES ('prod-40', 'MC/S-020', 'jai-shree-shyam-curtain', 'Jai Shree Shyam Curtain', 'Shyam Ji Decor', 'Shyam Baba Shringar & Flowers', '400.00', '500.00', '50', 'Customise (Price per metre)', 'Premium Fabric, Devotional Print, Vibrant Colorfast Dyes', 'Delhi, India', 'Master Craftsman Murli Prasad', '4.80', '31', '[\"\\/img-prodcut\\/IMG_4758.png\",\"\\/img-prodcut\\/IMG_4759.png\"]', '', 'Hanging a sacred Jai Shree Shyam curtain at the entrance of the mandir or home creates a divine threshold — blessing all who enter with Baba\'s grace and filling the space with devotional vibrations.', 'Beautiful handcrafted Jai Shree Shyam decorative curtain perfect for mandir entrances, pooja rooms, and home thresholds. Features the auspicious \'Jai Shree Shyam\' inscription with devotional motifs, vibrant colors, and premium fabric. Priced per metre with custom sizing available.', '1', '1', '[\"bestseller\",\"featured\",\"shyam-ji\",\"curtain\",\"jai-shree-shyam\",\"mandir-decor\",\"home-decor\"]', '2026-11-19 00:16:04', '2026-11-26 10:48:29');
INSERT INTO `mc_products` (`id`, `code`, `slug`, `name`, `category`, `subcategory`, `price`, `mrp`, `stock`, `size`, `material`, `origin`, `artist`, `rating`, `reviews_count`, `images`, `video`, `folklore`, `description`, `featured`, `bestseller`, `tags`, `created_at`, `updated_at`) VALUES ('prod-5', 'MC/L-005', 'rajsi-kamal-wall-art', 'Rajsi Kamal Wall Art (8x8”)', 'Lippan Art', 'Lippan Floral Art', '1599.00', '1999.00', '12', '8 x 8 inches', 'Sculpted Clay Relief, Mirror Elements, Gloss Varnish, MDF Board', 'Delhi, India', 'Master Craftsman Murli Prasad', '4.80', '16', '[\"\\/img-prodcut\\/IMG_3521.png\"]', '', 'The Rajsi Kamal (Royal Lotus) is revered as the divine seat of Goddess Lakshmi and Goddess Saraswati. Handcrafted lotus petals embedded with mirrors attract prosperity, creative wisdom, and peace into your home.', 'Celebrate royal craftsmanship with this 8x8 inch Rajsi Kamal Lippan wall art panel. Rich royal colors, hand-moulded petals, and central mirror inlays make this a standout piece for your pooja mandir or living space.', '1', '0', '[\"featured\",\"kamal\",\"lotus\",\"royal\"]', '2026-11-19 00:16:04', '2026-11-26 10:48:29');
INSERT INTO `mc_products` (`id`, `code`, `slug`, `name`, `category`, `subcategory`, `price`, `mrp`, `stock`, `size`, `material`, `origin`, `artist`, `rating`, `reviews_count`, `images`, `video`, `folklore`, `description`, `featured`, `bestseller`, `tags`, `created_at`, `updated_at`) VALUES ('prod-6', 'MC/L-006', 'evil-eye-wall-art', 'Evil Eye Wall Art (8x8”)', 'Vastu Species', 'Vastu Peacock (North-East)', '1599.00', '1999.00', '0', '8 x 8 inches', 'Clay Relief Paste, Inlay Mirrors, Cobalt & White Enamel, Engineered Wood', 'Delhi, India', 'Master Craftsman Murli Prasad', '5.00', '37', '[\"\\/img-prodcut\\/IMG_4148.png\"]', '', 'The Evil Eye (Nazar Suraksha) combined with reflective Lippan mirrors is an ancient protective talisman. According to Vastu and traditional beliefs, placing a mirror-inlaid eye at the foyer or entrance reflects envy and negative glances away from your sacred home.', 'Handcrafted Evil Eye Lippan Art panel in bold cobalt blue, turquoise, and white relief coils. Embedded with multiple high-reflection glass mirrors to protect your space and add a stylish contemporary heritage look.', '1', '1', '[\"bestseller\",\"featured\",\"evileye\",\"vastu\"]', '2026-11-19 00:16:04', '2026-11-26 10:48:29');
INSERT INTO `mc_products` (`id`, `code`, `slug`, `name`, `category`, `subcategory`, `price`, `mrp`, `stock`, `size`, `material`, `origin`, `artist`, `rating`, `reviews_count`, `images`, `video`, `folklore`, `description`, `featured`, `bestseller`, `tags`, `created_at`, `updated_at`) VALUES ('prod-7', 'MC/L-007', 'neel-tara-wall-art', 'Neel Tara Wall Art (8x8”)', 'Lippan Art', 'Lippan Mandala Art', '1599.00', '1999.00', '0', '8 x 8 inches', 'Clay Relief Paste, Diamond Mirror Glass, Sapphire Blue Base, MDF', 'Delhi, India', 'Master Craftsman Murli Prasad', '4.80', '14', '[\"\\/img-prodcut\\/IMG_4149.png\"]', '', 'The Neel Tara (Blue Star) represents the guiding celestial light and Dhruva Tara (Pole Star) in Indian astrology — a symbol of constancy, focus, inner clarity, and steady spiritual orientation.', 'Handcrafted 8x8 inch Neel Tara Lippan wall panel featuring geometric star motifs, hand-rolled clay borders, and glistening diamond mirrors on a deep sapphire background. Sealed with protective clear coating.', '0', '0', '[\"star\",\"mandala\",\"blue\"]', '2026-11-19 00:16:04', '2026-11-26 10:48:29');
INSERT INTO `mc_products` (`id`, `code`, `slug`, `name`, `category`, `subcategory`, `price`, `mrp`, `stock`, `size`, `material`, `origin`, `artist`, `rating`, `reviews_count`, `images`, `video`, `folklore`, `description`, `featured`, `bestseller`, `tags`, `created_at`, `updated_at`) VALUES ('prod-8', 'MC/L-008', 'swastik-mini-art', 'Swastik Mini Art (3”)', 'Diwali & Festive Decor', 'Lippan Spiritual Art', '149.00', '299.00', '30', '3 x 3 inches', 'Compact Wood Base, Clay Relief Paste, Mirror Inlays, Shubh Rakt Sindoor Finish', 'Delhi, India', 'Master Craftsman Murli Prasad', '4.90', '52', '[\"\\/img-prodcut\\/IMG_3681.png\"]', '', 'The Swastik is the oldest Vedic symbol of auspiciousness (Shubh), prosperity, and the four cardinal directions of cosmic harmony. Placing it at pooja altars or front doors invites divine blessings.', 'Handcrafted 3-inch Swastik mini Lippan art frame with fine clay relief contours and sparkling mirror details in sacred red and gold. Perfect for pooja mandirs, car dashboards, door thresholds, and festive return gifts.', '1', '1', '[\"bestseller\",\"mini-art\",\"spiritual\",\"swastik\",\"diwali\"]', '2026-11-19 00:16:04', '2026-11-26 10:48:29');
INSERT INTO `mc_products` (`id`, `code`, `slug`, `name`, `category`, `subcategory`, `price`, `mrp`, `stock`, `size`, `material`, `origin`, `artist`, `rating`, `reviews_count`, `images`, `video`, `folklore`, `description`, `featured`, `bestseller`, `tags`, `created_at`, `updated_at`) VALUES ('prod-9', 'MC/L-009', 'laxmi-charan-mini-art', 'Laxmi Charan Mini Art (3”)', 'Diwali & Festive Decor', 'Lippan Spiritual Art', '149.00', '299.00', '35', '3 x 3 inches', 'Compact Wood Base, Clay Relief, Mirrors, Auspicious Red & Gold', 'Delhi, India', 'Master Craftsman Murli Prasad', '5.00', '15', '[\"\\/img-prodcut\\/IMG_4150.png\"]', '', 'Laxmi Charan represents the auspicious holy footprints of Goddess Mahalakshmi. It is believed that installing holy charans at your threshold or pooja room ensures endless prosperity, joy, and fortune.', 'Auspicious 3-inch Maa Laxmi Charan mini Lippan artwork with delicate clay relief sculpting, sacred symbols, and reflective mirror highlights. An essential blessing for every Indian home and pooja room.', '1', '1', '[\"bestseller\",\"mini-art\",\"laxmi\",\"pooja\",\"diwali\"]', '2026-11-19 00:16:04', '2026-11-26 10:48:29');
