INSERT INTO `mc_reviews` (`id`, `product_id`, `name`, `location`, `rating`, `comment`, `date_text`, `is_approved`, `created_at`) VALUES ('rev-1', 'prod-1', 'Patron', 'Delhi', '5.0', 'The Peacock Jharokha is an absolute showstopper in our living room! The carved wood arch and mirror relief are royal and flawless. Packing was super secure.', '18 Aug 2026', '1', '2026-11-19 00:16:04');
INSERT INTO `mc_reviews` (`id`, `product_id`, `name`, `location`, `rating`, `comment`, `date_text`, `is_approved`, `created_at`) VALUES ('rev-10', 'prod-9', 'Patron', 'Delhi', '5.0', 'Laxmi Charan mini art in our mandir looks so auspicious and divine. Bright red and glistening mirrors.', '11 Aug 2026', '1', '2026-11-19 00:16:04');
INSERT INTO `mc_reviews` (`id`, `product_id`, `name`, `location`, `rating`, `comment`, `date_text`, `is_approved`, `created_at`) VALUES ('rev-11', 'prod-10', 'Patron', 'Delhi', '5.0', 'Lord Ganesha mini frame is perfect for my car dashboard and office table. Very neatly finished clay relief.', '13 Aug 2026', '1', '2026-11-19 00:16:04');
INSERT INTO `mc_reviews` (`id`, `product_id`, `name`, `location`, `rating`, `comment`, `date_text`, `is_approved`, `created_at`) VALUES ('rev-12', 'prod-11', 'Patron', 'Delhi', '5.0', 'Jai Jagannath! The sacred round eyes sculpted with Kutchi Lippan craft is very unique and devotional.', '07 Aug 2026', '1', '2026-11-19 00:16:04');
INSERT INTO `mc_reviews` (`id`, `product_id`, `name`, `location`, `rating`, `comment`, `date_text`, `is_approved`, `created_at`) VALUES ('rev-13', 'prod-12', 'Patron', 'Delhi', '5.0', 'Warli tribal folk dancers crafted in miniature Lippan relief. Very charming piece on natural wood base.', '06 Aug 2026', '1', '2026-11-19 00:16:04');
INSERT INTO `mc_reviews` (`id`, `product_id`, `name`, `location`, `rating`, `comment`, `date_text`, `is_approved`, `created_at`) VALUES ('rev-14', 'prod-13', 'Patron', 'Delhi', '5.0', 'Matsya Rang has lovely aquatic colors and smooth scales. Looks wonderful next to our indoor water fountain.', '05 Aug 2026', '1', '2026-11-19 00:16:04');
INSERT INTO `mc_reviews` (`id`, `product_id`, `name`, `location`, `rating`, `comment`, `date_text`, `is_approved`, `created_at`) VALUES ('rev-15', 'prod-14', 'Patron', 'Delhi', '5.0', 'Shubh Labh pair arrived well packed. Installed on our entrance door for Diwali preparation. Looks grand!', '19 Aug 2026', '1', '2026-11-19 00:16:04');
INSERT INTO `mc_reviews` (`id`, `product_id`, `name`, `location`, `rating`, `comment`, `date_text`, `is_approved`, `created_at`) VALUES ('rev-16', 'prod-15', 'Patron', 'Delhi', '5.0', 'Jai Shree Shyam! This Khatu Shyam Baba temple mini decor brings immense peace to our home altar. Beautiful Mor Pankh work.', '20 Aug 2026', '1', '2026-11-19 00:16:04');
INSERT INTO `mc_reviews` (`id`, `product_id`, `name`, `location`, `rating`, `comment`, `date_text`, `is_approved`, `created_at`) VALUES ('rev-17', 'prod-16', 'Patron', 'Delhi', '5.0', 'Lord Ganesha mini art is so vibrant and divine! Placed it right on our car dashboard and home mandir. The rhinestone work and pearl tassel are top notch.', '24 Aug 2026', '1', '2026-11-19 00:16:04');
INSERT INTO `mc_reviews` (`id`, `product_id`, `name`, `location`, `rating`, `comment`, `date_text`, `is_approved`, `created_at`) VALUES ('rev-18', 'prod-17', 'Patron', 'Delhi', '5.0', 'Har Har Mahadev! The Damru and Trishul clay relief work is stunning. Excellent mirror placement and deep spiritual vibe.', '25 Aug 2026', '1', '2026-11-19 00:16:04');
INSERT INTO `mc_reviews` (`id`, `product_id`, `name`, `location`, `rating`, `comment`, `date_text`, `is_approved`, `created_at`) VALUES ('rev-19', 'prod-18', 'Patron', 'Delhi', '5.0', 'Jai Shree Shyam! The Basanti Pushp Poshak is magnificent. Heavy zari embroidery, rich silk, and perfect fitting for Baba Shyam. Extremely pleased!', '26 Aug 2026', '1', '2026-11-19 00:16:04');
INSERT INTO `mc_reviews` (`id`, `product_id`, `name`, `location`, `rating`, `comment`, `date_text`, `is_approved`, `created_at`) VALUES ('rev-2', 'prod-1', 'Patron', 'Delhi', '5.0', 'Stunning craftsmanship! The peacock artwork combined with Kutchi Lippan mirrors gives genuine Rajasthani palace vibes. 100% worth every rupee.', '12 Aug 2026', '1', '2026-11-19 00:16:04');
INSERT INTO `mc_reviews` (`id`, `product_id`, `name`, `location`, `rating`, `comment`, `date_text`, `is_approved`, `created_at`) VALUES ('rev-20', 'prod-19', 'Patron', 'Delhi', '5.0', 'Pachrangi Hariyali poshak has divine colors and brilliant sequin work. Offered this for Ekadashi shringar and everyone praised it.', '26 Aug 2026', '1', '2026-11-19 00:16:04');
INSERT INTO `mc_reviews` (`id`, `product_id`, `name`, `location`, `rating`, `comment`, `date_text`, `is_approved`, `created_at`) VALUES ('rev-21', 'prod-20', 'Patron', 'Delhi', '5.0', 'Hariyali Kunj poshak in deep green looks majestic on Khatu Baba. The golden peacock embroidery and fine laces are superb.', '27 Aug 2026', '1', '2026-11-19 00:16:04');
INSERT INTO `mc_reviews` (`id`, `product_id`, `name`, `location`, `rating`, `comment`, `date_text`, `is_approved`, `created_at`) VALUES ('rev-22', 'prod-21', 'Patron', 'Delhi', '5.0', 'Mayura Nilam poshak in royal blue is breathtaking. The cloth quality and craftsmanship are truly devotional.', '27 Aug 2026', '1', '2026-11-19 00:16:04');
INSERT INTO `mc_reviews` (`id`, `product_id`, `name`, `location`, `rating`, `comment`, `date_text`, `is_approved`, `created_at`) VALUES ('rev-23', 'prod-22', 'Patron', 'Delhi', '5.0', 'Shahi Jamuni poshak has a royal imperial purple shade and delicate gotta borders. Delivered safely and on time.', '28 Aug 2026', '1', '2026-11-19 00:16:04');
INSERT INTO `mc_reviews` (`id`, `product_id`, `name`, `location`, `rating`, `comment`, `date_text`, `is_approved`, `created_at`) VALUES ('rev-24', 'prod-23', 'Patron', 'Delhi', '5.0', 'Rangrez Diamond poshak is rich in colors and diamond sparkle. Made with genuine love and devotion by Murli Prasad studio.', '28 Aug 2026', '1', '2026-11-19 00:16:04');
INSERT INTO `mc_reviews` (`id`, `product_id`, `name`, `location`, `rating`, `comment`, `date_text`, `is_approved`, `created_at`) VALUES ('rev-3', 'prod-2', 'Patron', 'Delhi', '5.0', 'The Lotus Mandala has completely elevated our pooja room ambience. The symmetrical clay coils and mirrors sparkle beautifully in ambient light.', '15 Aug 2026', '1', '2026-11-19 00:16:04');
INSERT INTO `mc_reviews` (`id`, `product_id`, `name`, `location`, `rating`, `comment`, `date_text`, `is_approved`, `created_at`) VALUES ('rev-33', 'prod-32', 'Patron', 'Delhi', '5.0', 'An extraordinary Lord Ganesha wall decor! The clay relief details, sparkling mirrors, and lotus design bring immense grace and divinity to our home temple entrance.', '22 Sep 2026', '1', '2026-11-19 00:16:04');
INSERT INTO `mc_reviews` (`id`, `product_id`, `name`, `location`, `rating`, `comment`, `date_text`, `is_approved`, `created_at`) VALUES ('rev-4', 'prod-3', 'Patron', 'Delhi', '5.0', 'The Teal and Gold combination is mesmerizing! Looks even better in person than the pictures. Received well packaged in wooden reinforcement.', '14 Aug 2026', '1', '2026-11-19 00:16:04');
