INSERT INTO `mc_reviews` (`id`, `product_id`, `name`, `location`, `rating`, `comment`, `date_text`, `is_approved`, `created_at`) VALUES ('rev-7', 'prod-6', 'Patron', 'Delhi', '5.0', 'Put this Evil Eye Lippan piece right above our front door. High quality mirrors, heavy board, and gorgeous cobalt blue shades.', '16 Aug 2026', '1', '2026-11-19 00:16:04');
