INSERT INTO `mc_seo_pages` (`id`, `page_key`, `page_name`, `url_path`, `meta_title`, `meta_description`, `meta_keywords`, `canonical_url`, `og_title`, `og_description`, `og_image`, `twitter_card`, `robots`, `schema_json`, `updated_at`) VALUES ('1', 'home', 'Home Page (Main Landing)', '/', 'Murli Creations | Handcrafted Lippan Art, Jharokhas & Sacred Wall Decor', 'Discover authentic handcrafted Lippan art, traditional Rajasthani Jharokhas, and sacred spiritual wall mandalas by master artisan Murli Prasad. Made in Delhi, India.', 'lippan art, handcrafted jharokha, khatu shyam decor, vastu decor', 'https://murlicreations.com/', 'Murli Creations | Handcrafted Lippan Art & Sacred Wall Decor', 'Direct from master artisan: 100% authentic clay relief mirror artwork.', '/img-prodcut/IMG_4041.png', 'summary_large_image', 'index, follow', '{}', '2026-11-19 00:42:20');
INSERT INTO `mc_seo_pages` (`id`, `page_key`, `page_name`, `url_path`, `meta_title`, `meta_description`, `meta_keywords`, `canonical_url`, `og_title`, `og_description`, `og_image`, `twitter_card`, `robots`, `schema_json`, `updated_at`) VALUES ('2', 'shop', 'Shop & Catalog', '/shop.php', 'Buy Lippan Art Online | Royal Jharokhas & Sacred Mandalas | Murli Creations', 'Browse our exclusive handcrafted collections: Peacock Lippan Jharokhas, Lotus Mandalas, Khatu Shyam Baba sacred shringar, and Vastu wall arts with Free Shipping in India.', 'buy lippan art online, peacock wall art, custom nameplate, khatu shyam ji poshak, wall decor online india', 'https://murlicreations.com/shop.php', 'Exclusive Handcrafted Art Collection | Murli Creations', 'Explore mastercrafted Lippan artworks, festive wall decor, and devotional pieces.', '/img-prodcut/IMG_4042.png', 'summary_large_image', 'index, follow', '', '2026-11-19 00:16:04');
INSERT INTO `mc_seo_pages` (`id`, `page_key`, `page_name`, `url_path`, `meta_title`, `meta_description`, `meta_keywords`, `canonical_url`, `og_title`, `og_description`, `og_image`, `twitter_card`, `robots`, `schema_json`, `updated_at`) VALUES ('3', 'product_detail', 'Product Details Template', '/product.php?id={id}', '{product_name} | Master Artisan Handcrafted Lippan Art | Murli Creations', 'Buy {product_name} handcrafted by master artisan Murli Prasad. Made with authentic clay relief paste, sparkling mirror inlays, and protected with moisture-resistant lacquer.', 'handcrafted {product_category}, authentic lippan mirror work, delhi art studio', 'https://murlicreations.com/product.php?id={id}', '{product_name} - Murli Creations', 'Handcrafted clay relief artwork with mirror inlays. Authentic Indian heritage for your home.', '{product_image}', 'summary_large_image', 'index, follow', '', '2026-11-19 00:16:04');
INSERT INTO `mc_seo_pages` (`id`, `page_key`, `page_name`, `url_path`, `meta_title`, `meta_description`, `meta_keywords`, `canonical_url`, `og_title`, `og_description`, `og_image`, `twitter_card`, `robots`, `schema_json`, `updated_at`) VALUES ('4', 'about', 'About Murli Creations', '/about.php', 'Our Heritage & Craftsmanship | About Murli Creations', 'Learn the journey of master craftsman Murli Prasad, preserving the centuries-old Kutchi Lippan Kaam relief art from his studio in Delhi, India.', 'lippan art history, murli prasad artist, traditional mud craft india, handmade artisan studio', 'https://murlicreations.com/about.php', 'The Soul of Kutchi Clay Art | About Murli Creations', 'A generational dedication to preserving India’s finest relief mud mirror art.', '/images/brand/founder.png', 'summary_large_image', 'index, follow', '', '2026-11-19 00:16:04');
INSERT INTO `mc_seo_pages` (`id`, `page_key`, `page_name`, `url_path`, `meta_title`, `meta_description`, `meta_keywords`, `canonical_url`, `og_title`, `og_description`, `og_image`, `twitter_card`, `robots`, `schema_json`, `updated_at`) VALUES ('5', 'founder_story', 'Founder Story', '/founder-story.php', 'The Hands Behind The Clay | Murli Prasad Founder Journey', 'Read the inspiring story of Murli Prasad — from childhood village clay modeling to crafting royal Lippan jharokhas adored across homes worldwide.', 'murli prasad bio, lippan artisan story, indian craft revival', 'https://murlicreations.com/founder-story.php', 'Meet Murli Prasad | Founder & Master Artisan', 'Discover how traditional clay, mirrors, and devotion become heirloom pieces.', '/images/brand/founder.png', 'summary_large_image', 'index, follow', '', '2026-11-19 00:16:04');
INSERT INTO `mc_seo_pages` (`id`, `page_key`, `page_name`, `url_path`, `meta_title`, `meta_description`, `meta_keywords`, `canonical_url`, `og_title`, `og_description`, `og_image`, `twitter_card`, `robots`, `schema_json`, `updated_at`) VALUES ('6', 'contact', 'Contact Us & Custom Orders', '/contact.php', 'Contact Murli Creations | Custom Commissions & Studio Visits', 'Get in touch for custom size Lippan art commissions, Khatu Shyam temple decor, or corporate gifts. Visit our Delhi studio or chat on WhatsApp.', 'custom lippan art order, commission handcrafted wall art, murli creations phone number', 'https://murlicreations.com/contact.php', 'Connect with Murli Creations Studio', 'Discuss your bespoke wall dimensions and devotional decor requirements directly with our team.', '/img-prodcut/IMG_4041.png', 'summary_large_image', 'index, follow', '', '2026-11-19 00:16:04');
INSERT INTO `mc_seo_pages` (`id`, `page_key`, `page_name`, `url_path`, `meta_title`, `meta_description`, `meta_keywords`, `canonical_url`, `og_title`, `og_description`, `og_image`, `twitter_card`, `robots`, `schema_json`, `updated_at`) VALUES ('7', 'blog', 'Art & Decor Blog', '/blog.php', 'Artisan Journal | Lippan Art Care, Vastu Tips & Styling Ideas', 'Expert guides on caring for clay mirror artworks, Vastu placement rules for peacock art, and festive decor inspiration.', 'lippan art cleaning tips, vastu directions for spiritual art, diy home decor ideas', 'https://murlicreations.com/blog.php', 'Murli Creations Artisan Journal', 'Tips, folklore, and heritage styling advice for art lovers.', '/img-prodcut/IMG_4043.png', 'summary_large_image', 'index, follow', '', '2026-11-19 00:16:04');
INSERT INTO `mc_site_settings` (`setting_key`, `setting_value`, `updated_at`) VALUES ('homepage_content', '{\n    \"hero\": {\n        \"badge\": \"Direct Studio Helpline & WhatsApp Support\",\n        \"title_main\": \"Authentic Handcrafted Lippan Art for\",\n        \"title_highlight\": \"Soulful Living Spaces\",\n        \"description\": \"Bring auspicious energy and timeless Indian grandeur into your home. Master artisan Murli Prasad blends sacred mud clay, precision mirrors, and vibrant devotions into heirloom-grade wall masterpieces.\",\n        \"cta_primary_text\": \"Explore Catalog\",\n        \"cta_primary_link\": \"/shop.php\",\n        \"cta_secondary_text\": \"About Our Studio\",\n        \"cta_secondary_link\": \"/about.php\",\n        \"image\": \"/img-prodcut/IMG_4041.png\"\n    },\n    \"stats\": [\n        {\n            \"count\": \"100\",\n            \"suffix\": \"%\",\n            \"decimals\": \"0\",\n            \"label\": \"Handcrafted Authenticity\",\n            \"desc\": \"Zero mass machinery — 100% sculpted and mirror-inlaid by artisan hands.\"\n        },\n        {\n            \"count\": \"100\",\n            \"suffix\": \"+\",\n            \"decimals\": \"0\",\n            \"label\": \"Spaces Blessed\",\n            \"desc\": \"Adorning pooja mandirs, luxury villas, and mindful residences across India.\"\n        },\n        {\n            \"count\": \"4.9\",\n            \"suffix\": \"★\",\n            \"decimals\": \"1\",\n            \"label\": \"Artisan Rating\",\n            \"desc\": \"Acclaimed by collectors for packaging safety, durability, and sacred aesthetic.\"\n        }\n    ],\n    \"seasonal_vibes\": {\n        \"badge\": \"Curated Seasonal Collections\",\n        \"title\": \"Seasonal Vibes & Festive Auspicious Curations\",\n        \"subtitle\": \"Curated themes matching Indian celebrations, festive light reflections, and sanctuary harmony.\",\n        \"cards\": [\n            {\n                \"id\": \"vibe-1\",\n                \"tag\": \"Festive Radiance\",\n                \"title\": \"Festive Door & Mandir Decor\",\n                \"desc\": \"Auspicious handcrafted Shubh-Labh and Swastik wall frames designed to welcome festive blessings.\",\n                \"link\": \"/shop.php?category=Diwali+%26+Festive+Decor\",\n                \"link_text\": \"Explore Festive Decor\",\n                \"image\": \"/img-prodcut/IMG_3426.png\"\n            },\n            {\n                \"id\": \"vibe-2\",\n                \"tag\": \"Pooja Mandir\",\n                \"title\": \"Divine Sanctum & Spiritual Peace\",\n                \"desc\": \"Handcrafted Khatu Shyam Baba and sacred deity reliefs sanctified for devotional prayer sanctuaries.\",\n                \"link\": \"/shop.php?category=Shyam+Ji+Decor\",\n                \"link_text\": \"Explore Spiritual Collection\",\n                \"image\": \"/img-prodcut/IMG_4158.png\"\n            },\n            {\n                \"id\": \"vibe-3\",\n                \"tag\": \"Contemporary Living\",\n                \"title\": \"Geometric Sacred Mandalas\",\n                \"desc\": \"Symmetrical sacred geometry and clay reliefs for living rooms, dining focal points, and office suites.\",\n                \"link\": \"/shop.php?category=Lippan+Art\",\n                \"link_text\": \"Explore Mandalas\",\n                \"image\": \"/img-prodcut/IMG_3519.png\"\n            }\n        ]\n    },\n    \"festive_offer\": {\n        \"enabled\": true,\n        \"badge\": \"Special Festive Celebration\",\n        \"title\": \"Claim 10% Off On Your First Handcrafted Artwork\",\n        \"description\": \"Every creation comes with certified authenticity, transit-insured bespoke packaging, and authentic brass hooks ready to grace your walls.\",\n        \"coupon_code\": \"MURLI10\",\n        \"discount_label\": \"10% FLAT OFF\",\n        \"button_text\": \"Shop Auspicious Masterpieces\",\n        \"button_link\": \"/shop.php\"\n    },\n    \"story\": {\n        \"badge\": \"Our Story • A Daughter\'s Tribute\",\n        \"title\": \"From a Mother’s Hands to Murli Creations\",\n        \"lead\": \"A journey of handmade art, memories, devotion and love.\",\n        \"quote\": \"“What started with watching my mother create with her hands became my own journey of creating with love.”\",\n        \"author\": \"Murli Creations\",\n        \"promise\": \"Handcrafted with Love • Inspired by Tradition • Created to Be Cherished\",\n        \"highlights\": [\n            {\n                \"title\": \"A Mother\'s Inspiration\",\n                \"desc\": \"Childhood memories of watching my mother decorate earthen pots and wool crafts with patience and love.\"\n            },\n            {\n                \"title\": \"Inspired by Shyam Baba\",\n                \"desc\": \"Blessed beginnings crafting devotional poshak, pearl shringar, and temple décor offered at the Lord\'s feet.\"\n            },\n            {\n                \"title\": \"Authentic Lippan Art\",\n                \"desc\": \"Centuries-old mud and mirror relief art sculpted by hand to bring sacred harmony and beauty to modern homes.\"\n            }\n        ],\n        \"image\": \"/img-prodcut/IMG_3495.png\"\n    },\n    \"custom_commission\": {\n        \"badge\": \"Bespoke Artistry\",\n        \"title\": \"Commission a Custom Masterpiece\",\n        \"description\": \"Looking for specific dimensions, auspicious color palettes, or deity themes for your pooja mandir or luxury interior? Our master artisan collaborates directly with homeowners and interior designers.\",\n        \"cta_text\": \"Chat on WhatsApp for Custom Orders\",\n        \"cta_link\": \"https://wa.me/919582316454?text=Hello%20Murli%20Creations,%20I\'d%20like%20to%20inquire%20about%20a%20custom%20artwork.\"\n    },\n    \"faqs\": [\n        {\n            \"question\": \"How are the delicate mirrors and clay reliefs protected during shipping?\",\n            \"answer\": \"Every artwork is protected with multi-layer high-density cushioning, moisture-resistant film, and heavy-duty reinforced packaging to ensure 100% safe transit across India.\",\n            \"q\": \"How are the delicate mirrors and clay reliefs protected during shipping?\",\n            \"a\": \"Every artwork is protected with multi-layer high-density cushioning, moisture-resistant film, and heavy-duty reinforced packaging to ensure 100% safe transit across India.\"\n        },\n        {\n            \"question\": \"Are these authentic handmade Lippan artworks?\",\n            \"answer\": \"Yes, each artwork is 100% hand-sculpted by Master Craftsman Murli Prasad in our Delhi studio, using traditional clay relief paste, genuine glass mirrors, and premium wooden backings.\",\n            \"q\": \"Are these authentic handmade Lippan artworks?\",\n            \"a\": \"Yes, each artwork is 100% hand-sculpted by Master Craftsman Murli Prasad in our Delhi studio, using traditional clay relief paste, genuine glass mirrors, and premium wooden backings.\"\n        },\n        {\n            \"question\": \"Test Question 3: Can I request custom sizes?\",\n            \"answer\": \"Yes, custom dimensions are available upon request via our WhatsApp helpline.\",\n            \"q\": \"Test Question 3: Can I request custom sizes?\",\n            \"a\": \"Yes, custom dimensions are available upon request via our WhatsApp helpline.\"\n        }\n    ]\n}', '2026-11-21 12:51:29');
INSERT INTO `mc_site_settings` (`setting_key`, `setting_value`, `updated_at`) VALUES ('site_settings', '{\n    \"announcement\": {\n        \"enabled\": true,\n        \"text\": \"Festive Offer: Use code {coupon} for 10% OFF on all orders!\",\n        \"coupon_code\": \"MURLI10\",\n        \"badge\": \"✨ Special Celebration ✨\",\n        \"link\": \"/shop.php\"\n    },\n    \"studio\": {\n        \"name\": \"Murli Creations\",\n        \"tagline\": \"Handcrafted Lippan Art & Sacred Devotional Heritage\",\n        \"founder\": \"Master Craftsman Murli Prasad\",\n        \"location\": \"Pitampura, Delhi, India\",\n        \"address\": \"ITL Twin Tower, Netaji Subhash Place, Pitampura, Delhi - 110034, India\",\n        \"phone\": \"+91 95823 16454\",\n        \"whatsapp\": \"+91 95823 16454\",\n        \"email\": \"contact@murlicreations.com\",\n        \"hours\": \"Mon - Sat: 10:00 AM - 7:30 PM (IST)\"\n    },\n    \"shipping\": {\n        \"free_threshold\": 2500,\n        \"standard_charge\": 199,\n        \"transit_safe_note\": \"100% Insured Safe Doorstep Delivery\",\n        \"dispatch_time\": \"Dispatched in 3 to 5 business days\",\n        \"serviceable_area\": \"Delivering Exclusively across Delhi & NCR\"\n    },\n    \"social\": {\n        \"instagram\": \"https://instagram.com/murlicreationsofficial\",\n        \"facebook\": \"https://www.facebook.com/61590873986487\",\n        \"linkedin\": \"https://www.linkedin.com/company/murli-creations\",\n        \"linktree\": \"https://linktr.ee/murlicreations\",\n        \"pinterest\": \"https://pinterest.com/murlicreations\",\n        \"whatsapp\": \"https://wa.me/919582316454\",\n        \"youtube\": \"https://youtube.com/@murlicreations\"\n    },\n    \"footer\": {\n        \"about_text\": \"Sacred mud & mirror art handcrafted by Murli Prasad. Bringing positive energy, devotion, and traditional Indian grandeur to homes across the globe.\",\n        \"copyright\": \"© 2026 Murli Creations. Handcrafted in India with Devotion. All Rights Reserved.\"\n    },\n    \"faqs\": [\n        {\n            \"question\": \"How are the delicate mirrors and clay reliefs protected during shipping?\",\n            \"answer\": \"Every artwork is protected with multi-layer high-density cushioning, moisture-resistant film, and heavy-duty reinforced packaging to ensure 100% safe transit across India.\",\n            \"q\": \"How are the delicate mirrors and clay reliefs protected during shipping?\",\n            \"a\": \"Every artwork is protected with multi-layer high-density cushioning, moisture-resistant film, and heavy-duty reinforced packaging to ensure 100% safe transit across India.\"\n        },\n        {\n            \"question\": \"Are these authentic handmade Lippan artworks?\",\n            \"answer\": \"Yes, each artwork is 100% hand-sculpted by Master Craftsman Murli Prasad in our Delhi studio, using traditional clay relief paste, genuine glass mirrors, and premium wooden backings.\",\n            \"q\": \"Are these authentic handmade Lippan artworks?\",\n            \"a\": \"Yes, each artwork is 100% hand-sculpted by Master Craftsman Murli Prasad in our Delhi studio, using traditional clay relief paste, genuine glass mirrors, and premium wooden backings.\"\n        },\n        {\n            \"question\": \"Test Question 3: Can I request custom sizes?\",\n            \"answer\": \"Yes, custom dimensions are available upon request via our WhatsApp helpline.\",\n            \"q\": \"Test Question 3: Can I request custom sizes?\",\n            \"a\": \"Yes, custom dimensions are available upon request via our WhatsApp helpline.\"\n        }\n    ]\n}', '2026-11-21 12:51:29');
